function validateMatch(match) {
  if (!match) return true;
  const state = match.groundBallInPlayState, admission = match.receiverSourceAdmission;
  if ([state, match.activeSituation?.executionState].some(o => ["receiverExecutionVersion", "receiverV2Execution", "receiverModelAdmission"].some(k => own(o, k))) ||
    own(match, "officialReceiverExecutionVersion") && match.officialReceiverExecutionVersion !== V.official || own(match, "receiverExecutionVersion") && match.receiverExecutionVersion !== V.official) reject("actual v2 execution not implemented");
  const any = own(match, "receiverSourceFormatVersion") || own(match, "receiverSourceAdmission") || presentState(state) ||
    own(match.activeSituation, "receiverSourcePin") || own(match.activeSituation?.contextSnapshot, "receiverSourcePin") || own(match.activeSituation?.executionState, "receiverSourcePin") || own(match.lastClosedSituationSummary, "receiverSourcePin");
  if (!any) return true; // genuine omitted legacy metadata; never build a snapshot here.
  if (match.receiverSourceFormatVersion !== V.format || !exact(admission, ["formatVersion", "snapshot", "pin"]) || admission.formatVersion !== V.format) reject("required match format/admission");
  validatePair(admission.snapshot, admission.pin);
  const b = admission.snapshot.body;
  if (b.physical.matchId !== match.id) reject("match identity");
  if (presentState(state)) {
    if (state.receiverSourceFormatVersion !== V.format || !own(state, "receiverSourceSnapshot") || !own(state, "receiverSourcePin")) reject("required handoff source fields");
    validatePair(state.receiverSourceSnapshot, state.receiverSourcePin);
    if (!same(state.receiverSourceSnapshot, admission.snapshot) || !same(state.receiverSourcePin, admission.pin) || state.identity !== b.physical.playId ||
      state.physicalTruth?.identity !== b.physical.physicalIdentity || state.runnerRealization?.batterRunner?.runnerId !== b.original.batterRunner || state.defensiveAccess?.playerPosition !== "游擊手" ||
      state.firstBaseContext || state.firstBaseExecution || state.thirdBaseExecution) reject("original handoff/actor/physical copies");
    if (!same(state.defensiveAccess?.secureCapabilities, b.capabilitySource.thrower) || state.defensiveAccess?.reachResolution?.identity !== b.capabilitySource.reference) reject("original thrower capability/reference");
    if (!state.settlementApplied && (match.outs !== b.original.outs || !same(match.runners, b.original.bases))) reject("original pre-settlement outs/bases");
    if (!state.settlementApplied) {
      if (!Roster || match.defenseTeam !== b.original.defenseTeam) reject("original defense team/roster owner");
      const roster = match.rosters?.[b.original.defenseTeam], ss = Roster.getCurrentDefender(roster, "SS"), first = Roster.getCurrentDefender(roster, "1B");
      if (ss?.id !== b.original.thrower.actorId || first?.id !== b.original.receiver.actorId) reject("original active roster actors");
      const raw = Object.fromEntries(["defense", "speed", "arm", "contact"].map(k => [k, Number.isFinite(first[k]) ? first[k] : null]));
      if (!same(raw, b.capabilitySource.receiver)) reject("original raw receiver capabilities");
    }
    const pa = match.ordinaryDefensivePlateAppearanceState;
    if (pa?.paIdentity !== b.physical.plateAppearanceId || pa?.battedBallPhysicalTruth?.identity !== b.physical.contactId) reject("original PA/contact");
    const binding = executionBinding(state);
    if (binding !== null && (!own(state, "receiverSourceExecutionBinding") || !same(binding, state.receiverSourceExecutionBinding))) reject("required original execution binding");
    if (binding === null && own(state, "receiverSourceExecutionBinding")) reject("pending cannot contain execution binding");
  } else if (state?.identity === b.physical.playId) reject("new source handoff cannot omit metadata");
  assertLifecycle(match.activeSituation);
  const active = match.activeSituation;
  if (active?.sourcePhysicalStateRef === b.physical.playId) {
    if (!same(active.receiverSourcePin, admission.pin)) reject("required active lifecycle pin");
    if (active.createdAt?.outs !== b.original.outs || !same(active.createdAt?.bases, b.original.bases)) reject("lifecycle original outs/bases");
    if (state?.shortstopExecution && (!own(active, "receiverSourceExecutionBinding") || !same(active.receiverSourceExecutionBinding, state.receiverSourceExecutionBinding))) reject("required active source binding");
  }
  const summary = match.lastClosedSituationSummary;
  if (state?.settlementApplied && summary?.situationId?.includes(b.physical.playId) && !own(summary, "receiverSourcePin")) reject("closed source pin missing");
  if (own(summary, "receiverSourcePin")) { assertReference(summary.receiverSourcePin);
    if (summary.receiverSourcePin.physical.playId === b.physical.playId && !same(summary.receiverSourcePin, admission.pin)) reject("closed pin copy");
    if (summary.receiverSourcePin.physical.playId === b.physical.playId && summary.outsBefore !== b.original.outs) reject("closed original outs");
    if (summary.receiverSourcePin.physical.playId === b.physical.playId && state?.shortstopExecution && (!own(summary, "receiverSourceExecutionBinding") || !same(summary.receiverSourceExecutionBinding, state.receiverSourceExecutionBinding))) reject("closed execution binding"); }
  return true;
}

function canonical(o, active = new Set()) {
  if (o === null || typeof o === "boolean") return JSON.stringify(o);
  if (typeof o === "string") { for (let i = 0; i < o.length; i++) { const c = o.charCodeAt(i); if (c >= 0xd800 && c <= 0xdbff) { const n = o.charCodeAt(++i); if (!(n >= 0xdc00 && n <= 0xdfff)) throw Error("unpaired surrogate"); } else if (c >= 0xdc00 && c <= 0xdfff) throw Error("unpaired surrogate"); } return JSON.stringify(o); }
  if (typeof o === "number" && Number.isFinite(o) && !Object.is(o, -0)) return JSON.stringify(o);
  if (!o || typeof o !== "object" || active.has(o)) throw Error("non-JSON metadata");
  const proto = Object.getPrototypeOf(o); if (!Array.isArray(o) && proto !== null && Object.getPrototypeOf(proto) !== null) throw Error("nonplain metadata");
  for (const k of Reflect.ownKeys(o)) if (typeof k === "symbol" || !own(Object.getOwnPropertyDescriptor(o, k), "value")) throw Error("metadata accessor");
  active.add(o); let s;
  if (Array.isArray(o)) { if (Object.keys(o).length !== o.length || o.some((_, i) => !own(o, i))) throw Error("sparse metadata"); s = "[" + o.map(x => canonical(x, active)).join(",") + "]"; }
  else s = "{" + Object.keys(o).sort().map(k => JSON.stringify(k) + ":" + canonical(o[k], active)).join(",") + "}";
  active.delete(o); return s;
}

function recordGroundBallSituationResolution(match, resolution) {
  if (!match || !resolution || typeof MatchSituationLifecycle === "undefined") return null;
  let situation = MatchSituationLifecycle.normalizeSituation(match.activeSituation);
  if (!situation || situation.type !== MatchSituationLifecycle.TYPES.groundBallDefensiveDecision
    || situation.lifecycleState !== "executing") return situation;
  validateHighSchoolDecisionThrowState(match);
  const handoff = match.groundBallInPlayState;
  if (handoff?.firstBaseExecution && Object.entries(handoff.firstBaseExecution.resolution)
    .some(([key, value]) => JSON.stringify(resolution[key]) !== JSON.stringify(value))) throw new Error("Stale first-base settlement execution facts");
  if (handoff?.thirdBaseExecution && Object.entries(handoff.thirdBaseExecution.resolution)
    .some(([key, value]) => JSON.stringify(resolution[key]) !== JSON.stringify(value))) throw new Error("Stale 3B settlement execution facts");
  if (handoff?.shortstopExecution && Object.entries(handoff.shortstopExecution.resolution)
    .some(([key, value]) => JSON.stringify(resolution[key]) !== JSON.stringify(value))) throw new Error("Stale SS settlement execution facts");
  if (handoff?.supported && !handoff.settlementApplied && !handoff.secureResolution
    && handoff.defensiveAccess?.reachResolution && resolution.playerLeg?.control
    && typeof DefensiveReachSecureFoundation !== "undefined") {
    assertHighSchoolDetailedResponsibility(match, handoff.physicalTruth, "2B", "player");
    const securedHandoff = BattedBallGroundDefense.normalizeHandoff({ ...handoff,
      secureResolution: DefensiveReachSecureFoundation.projectGroundControl(handoff.defensiveAccess.reachResolution, resolution.playerLeg.control, resolution.controlEvidence) });
    const decisionThrowState = projectHighSchoolControlledDecisionThrow(match, resolution, securedHandoff);
    match.groundBallInPlayState = BattedBallGroundDefense.normalizeHandoff({ ...securedHandoff, ...(decisionThrowState ? { decisionThrowState } : {}) });
    if (decisionThrowState && typeof DefensiveRunnerThrowSettlementFoundation !== "undefined") {
      const route = decisionThrowState.activeSelection?.route || decisionThrowState.selection?.route;
      const receiverFact = route?.routeId === "initiate463" ? resolution.teammateLeg?.shortstopReceive
        : route?.routeId === "preventRunHome" && !resolution.reassessed ? resolution.teammateLeg?.catcherReceive : resolution.teammateLeg?.receiver;
      const runnerThrowTiming = DefensiveRunnerThrowSettlementFoundation.projectExistingTiming({ stage: decisionThrowState,
        runnerState: handoff.runnerPhysicalStates?.find(r => r.runnerId === route?.targetRunnerId),
        windowState: resolution.firstLegTimingWindow?.state || "expired", receiverFact: receiverFact || "unavailable",
        tagFact: resolution.homeTagLeg?.arrivalComparison || null });
      match.groundBallInPlayState = BattedBallGroundDefense.normalizeHandoff({ ...match.groundBallInPlayState, runnerThrowTiming });
    }
  }
  if (resolution.reassessment) {
    const remaining = (resolution.reassessment.availableRouteIds || []).map(routeId => ({ routeId }));
    situation = MatchSituationLifecycle.beginReassessment(situation, {
      trigger: resolution.reassessment.reason,
      updatedPhysicalState: {
        firstLegState: resolution.firstLegState || null,
        continuationState: resolution.continuationState || null,
        forceState: resolution.reassessment.forceState || null
      },
      remainingLegalRoutes: remaining,
      requiresDecision: false,
      firstLegApplied: resolution.firstLegState?.status === "completed"
    });
  }
  situation = MatchSituationLifecycle.resolveSituation(situation, {
    physicalOutcomeRef: `${situation.situationId}|physical-resolution`,
    outsDelta: resolution.outsCreated,
    runsDelta: resolution.runsAllowed,
    runnerActorOutcomes: resolution.runnerChanges,
    executionEvidence: match.groundBallInPlayState?.runnerThrowTiming || match.groundBallInPlayState?.shortstopExecution ? resolution : null,
    reason: resolution.reassessment ? "postExecutionReassessmentComplete" : "groundBallExecutionComplete"
  });
  match.activeSituation = situation;
  return situation;
}

